function StepOne({draft,set,ageMode,setAgeMode}:{draft:Draft;set:(key:string,value:any)=>void;ageMode:'age'|'birth';setAgeMode:(mode:'age'|'birth')=>void}){
 const choose=(mode:'age'|'birth')=>{setAgeMode(mode);set('ageSource',mode==='birth'?'birthDate':'age');if(mode==='age')set('birthDate','');else set('age',undefined)}
 return <><h1>{R.about}</h1><p>Это поможет подобрать стартовый ритм без обещаний и диагнозов.</p><p className="onboarding-field-intro">Как удобнее указать возраст?</p><div className="onboarding-age-mode"><button type="button" className={ageMode==='age'?'selected':''} onClick={()=>choose('age')}>Возраст</button><button type="button" className={ageMode==='birth'?'selected':''} onClick={()=>choose('birth')}>Дата рождения</button></div><div className="onboarding-grid"><label>{ageMode==='age'?R.age:'Дата рождения'}<input aria-label={ageMode==='age'?R.age:'Дата рождения'} name={ageMode==='age'?'onboarding-age':'onboarding-birth-date'} type={ageMode==='age'?'number':'date'} inputMode={ageMode==='age'?'numeric':undefined} value={ageMode==='age'?draft.age??'':draft.birthDate??''} min={ageMode==='age'?'18':undefined} max={ageMode==='age'?'100':undefined} placeholder={ageMode==='age'?'Например, 31':undefined} onChange={e=>set(ageMode==='age'?'age':'birthDate',e.target.value)}/><small>{ageMode==='age'?'Сохраним как приблизительный возраст.':'Возраст рассчитаем автоматически по дате рождения.'}</small></label><label>{R.height}<input name="onboarding-height" type="number" inputMode="numeric" value={draft.heightCm??''} min="120" max="230" placeholder="Например, 178" onChange={e=>set('heightCm',e.target.value)}/></label><label>{R.weight}<input name="onboarding-weight" type="text" inputMode="decimal" pattern="[0-9]*[.,]?[0-9]*" value={localDecimal(draft.weightKg)} placeholder="Например, 82,5" onChange={e=>set('weightKg',e.target.value)} onBlur={e=>set('weightKg',localDecimal(e.target.value))}/></label><label>{R.sex}<select value={draft.sex} onChange={e=>set('sex',e.target.value)}><option value="male">Мужской</option><option value="female">Женский</option><option value="unspecified">Не указывать</option></select><small>{draft.sex==='unspecified'?'Используем усреднённый диапазон калорий.':'Используется только для расчёта ориентиров.'}</small></label></div></>}
function GoalWeight({goal,value,onChange}:{goal:string|undefined;value:any;onChange:(value:any)=>void}){if(!['lose_weight','gain_muscle'].includes(goal||''))return null;const unknown=value===undefined||value===null;return <section className="onboarding-goal-weight"><p>К какому весу хочешь прийти?</p><div className="onboarding-target-mode"><button type="button" className={!unknown?'selected':''} onClick={()=>unknown&&onChange('')}>Указать вес</button><button type="button" className={unknown?'selected':''} onClick={()=>onChange(null)}>Пока не знаю</button></div>{!unknown&&<label>Вес, кг<input type="text" inputMode="decimal" pattern="[0-9]*[.,]?[0-9]*" value={localDecimal(value)} min="30" max="350" placeholder="Например, 82" onChange={e=>onChange(e.target.value?e.target.value:null)} onBlur={e=>onChange(e.target.value?localDecimal(e.target.value):null)}/></label>}</section>}
